#include "rsmicro/rsm_runtime.h"
#include "rsm_test_hal.h"
#include <stdio.h>
#include <stdlib.h>
int main(int argc,char**argv){FILE*f;long n;uint8_t*x;size_t need;void*a;rsm_runtime_t r;rsm_test_hal_t th;rsm_hal_t h;rsm_runtime_diagnostics_t d;if(argc!=2){fprintf(stderr,"usage: %s image.rsm\n",argv[0]);return 2;}f=fopen(argv[1],"rb");if(!f)return 2;fseek(f,0,SEEK_END);n=ftell(f);rewind(f);x=malloc((size_t)n);if(!x||fread(x,1,(size_t)n,f)!=(size_t)n)return 2;fclose(f);if(rsm_runtime_required_memory(x,(size_t)n,&need)){puts("invalid image");return 1;}a=malloc(need);rsm_test_hal_init(&th,&h);if(!a||rsm_runtime_init(&r,a,need,&h,&th)||rsm_runtime_load_image(&r,x,(size_t)n)||rsm_runtime_set_mode(&r,RSM_MODE_RUN)||rsm_runtime_scan(&r)){const rsm_fault_t *q=rsm_runtime_last_fault(&r);printf("runtime fault: %s opcode=%u instruction=%u tag=%u\n",q&&q->message_id?q->message_id:"load",q?q->opcode:0,q?q->instruction_id:0,q?q->tag_id:0);return 1;}rsm_runtime_get_diagnostics(&r,&d);printf("mode=RUN scans=%llu tags=%u instructions=%u hal_writes=%llu\n",(unsigned long long)d.scan_count,d.tag_count,d.instruction_count,(unsigned long long)th.writes);rsm_runtime_set_mode(&r,RSM_MODE_PROGRAM);rsm_runtime_deinit(&r);free(a);free(x);return 0;}
